import json
import math
import re
from collections import Counter
from datetime import date, datetime, timedelta, timezone
from typing import Any, TypeGuard
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

DiscoveryError = RuntimeError

RowError = ValueError

def equal_cell(before: Any, after: Any, grist_type: str) -> bool:
    if isinstance(before, list) and before and (before[0] != 'L'):
        raise RowError('Valeur Grist masquée, en erreur ou non calculée.')
    if grist_type.split(':', 1)[0] in {'ChoiceList', 'RefList'}:
        if before == ['L']:
            before = None
    if isinstance(before, bool) != isinstance(after, bool):
        return False
    return before == after

def finalize(context: dict[str, Any]) -> dict[str, Any]:
    if context['config']['mode'] != 'write':
        raise DiscoveryError("La simulation ne doit pas passer par la finalisation d'écriture.")
    report = context['report']
    operations = context['operations']
    results = object_list(context.get('write_results'), 'write_results')
    if len(operations) != len(results):
        raise DiscoveryError("Résultats d'écriture incomplets ; conserver le checkpoint de reprise.")
    mapping = context['config']['mapping']
    target = object_list(context['verification_records'].get('records'), 'verification_records')
    index, by_id, anomalies = index_grist(target, mapping['record_key']['target_column'], mapping['target']['table_id'])
    fields = {field['grist_column_id']: field for field in mapping['fields']}
    verified = 0
    write_errors = []
    for operation, response in zip(operations, results):
        key = operation['airtable_record_id']
        status = response.get('status_code')
        if response.get('airtable_record_id') != key or isinstance(status, bool) or (not isinstance(status, int)) or (not 200 <= status < 300):
            write_errors.append({'airtable_record_id': key, 'code': 'write_http_error', 'status_code': status})
            continue
        matches = index.get(key, [])
        if len(matches) != 1:
            write_errors.append({'airtable_record_id': key, 'code': 'write_key_not_unique'})
            continue
        current = by_id[matches[0]]
        try:
            for column_id, expected in operation['fields'].items():
                if column_id in current.get('errors', {}) or column_id not in current['fields'] or (not equal_cell(current['fields'][column_id], expected, fields[column_id]['grist_type'])):
                    raise RowError('La valeur enregistrée ne correspond pas au plan.')
        except RowError:
            write_errors.append({'airtable_record_id': key, 'code': 'write_verification_failed'})
        else:
            verified += 1
    retries = sorted({*report['retry_airtable_ids'], *[error['airtable_record_id'] for error in write_errors]})
    report['write_errors'] = write_errors
    report['summary'].update(verified_writes=verified, write_failures=len(write_errors), pending_retries=len(retries), grist_key_anomalies=len(anomalies) + sum((1 for issue in report['grist_key_anomalies'] if issue['table_id'] != mapping['target']['table_id'])))
    final_state = {'version': 1, 'mapping_fingerprint': context['config']['mapping_fingerprint'], 'cursor': context['started_at'], 'retry_ids': retries, 'last_summary': report['summary']}
    return {**context, 'final_payload': json.dumps(final_state, ensure_ascii=False)}

def index_grist(records: list[dict[str, Any]], key_column: str, table_id: str) -> tuple[dict[str, list[int]], dict[int, dict[str, Any]], list[dict[str, Any]]]:
    index: dict[str, list[int]] = {}
    by_id: dict[int, dict[str, Any]] = {}
    anomalies = []
    for record in records:
        row_id = record.get('id')
        if isinstance(row_id, bool) or not isinstance(row_id, int) or row_id <= 0 or (row_id in by_id):
            raise DiscoveryError('Identifiant de ligne Grist absent, invalide ou répété.')
        fields = object_value(record.get('fields'), 'Grist record fields')
        by_id[row_id] = record
        key = fields.get(key_column)
        if not record_id(key):
            anomalies.append({'table_id': table_id, 'grist_record_id': row_id, 'code': 'missing_key' if key is None or key == '' else 'invalid_key'})
            continue
        index.setdefault(key, []).append(row_id)
    for key, ids in index.items():
        if len(ids) > 1:
            anomalies.append({'table_id': table_id, 'airtable_record_id': key, 'grist_record_ids': ids, 'code': 'duplicate_key'})
    return (index, by_id, anomalies)

def object_list(value: Any, context: str) -> list[dict[str, Any]]:
    if not isinstance(value, list):
        raise DiscoveryError(f'{context}: liste JSON attendue.')
    return [object_value(item, context) for item in value]

def object_value(value: Any, context: str) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise DiscoveryError(f'{context}: objet JSON attendu.')
    return value

def record_id(value: Any) -> TypeGuard[str]:
    return isinstance(value, str) and re.fullmatch('rec[A-Za-z0-9]+', value) is not None

return [{"json": finalize(_items[0]["json"])}]

